style.css:
@-moz-document domain("mail.google.com") {
/* Background Image */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-image: url('https://images.unsplash.com/photo-1489914099268-8d7d9b7bcd92'); /* Snowy Winter Background */
        background-size: cover;
        background-position: center;
        background-attachment: fixed;
        z-index: -1;
    }

    /* Main Background */
    body, .nH, .BltHke, .no {
        background-color: rgba(240, 248, 255, 0.9) !important; /* Light Icy Blue */
    }

    /* Sidebar and Menus */
    .gb_Xc, .TO, .n6, .aKw {
        background-color: rgba(173, 216, 230, 0.9) !important; /* Frosty Blue */
        color: #003366 !important; /* Deep Blue Text */
    }

    /* Inbox Emails */
    .zA {
        background-color: rgba(224, 247, 250, 0.8) !important; /* Ice Blue */
        color: #003366 !important;
    }

    /* Unread Emails */
    .zA.zE {
        background-color: rgba(176, 224, 230, 0.9) !important; /* Slightly Darker Ice Blue */
        font-weight: bold !important;
    }

    /* Buttons */
    .T-I, .T-I-JW, .T-I-KE {
        background-color: #4682b4 !important; /* Winter Sky Blue */
        color: #fff !important;
    }

    /* Hover Effects */
    .T-I:hover, .zA:hover {
        background-color: #5f9ea0 !important; /* Cool Teal Blue */
        color: #fff !important;
    }

    /* Borders */
    .BltHke, .nH, .gb_Xc {
        border-color: #5f9ea0 !important; /* Soft Winter Teal */
    }

    /* Text Colors */
    * {
        color: #003366 !important; /* Deep Blue Text */
    }

    /* Disable Text Selection */
    * {
        user-select: none !important;
        outline: none !important;
    }
}
